fields.ValueConv:
my $size = length $val;
return \$val if $size < 12 or not $$self{OPTIONS}{Binary};
my $len = Get16u(\$val, 2);
my $str = '';
SetByteOrder('II');
my $pos = 12;
while ($pos + $len <= $size) {
    my $s1 = Get16u(\$val, $pos);
    # s2: 7=take-off?, 3=moving, 4=hovering, 9=landing?, 2=landed
    my $s2 = Get16u(\$val, $pos + 2);
    $str .= "$s1 $s2";
    my $num = int(($len-4)/4);
    my ($i, $v);
    for ($i=0; $i<$num; ++$i) {
        my $pt = $pos + 4 + $i * 4;
        if ($i > 0 && $i < 4) {
            $v = GetFloat(\$val, $pt); # pitch/roll/yaw
        } else {
            $v = Get32u(\$val, $pt);
            # convert time to sec, and speed(NC)/altitude to metres
            $v /= 1000 if $i <= 5;
        }
        $str .= " $v";
    }
    $str .= "\n";
    $pos += $len;
}
SetByteOrder('MM');
return \$str;

